INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6604103, 985312, 61396, '<td valign="top">This is totally Tim Burton. I especially like the tiny faces pouring out of the main body. I applaud your BraVerY (pardon the outburst) and insight.<br/> <br/>ETA: just found <a href="//www.youtube.com/watch?v=Tn6S_jfbgVI" rel="nofollow" target="_blank">an imagery of the loyal assistant</a>, as depicted by the young Tim Burton. I prefer the subtlety of your find better.</td>', 'This is totally Tim Burton. I especially like the tiny faces pouring out of the main body. I applaud your BraVerY (pardon the outburst) and insight. ETA: just found an imagery of the loyal assistant, as depicted by the young Tim Burton. I prefer the subtlety of your find better.', '2011-11-26 19:17:08.000000', NULL, 1),
(6604104, 985226, 61396, '<td valign="top">Just my opinion: you failed to imitate Tim Burton''s crow. Yours is much more intimidating, especially considering its angle of attack with respect to the human figure. The thin lampposts do look like Tim Burton''s figures, so overall you are doing fine. The casual placement of the lady''s bicycles allow the viewers'' imagination contemplate on how did we get here, and what comes next.</td>', 'Just my opinion: you failed to imitate Tim Burton''s crow. Yours is much more intimidating, especially considering its angle of attack with respect to the human figure. The thin lampposts do look like Tim Burton''s figures, so overall you are doing fine. The casual placement of the lady''s bicycles allow the viewers'' imagination contemplate on how did we get here, and what comes next.', '2011-11-26 19:18:16.000000', NULL, 1),
(6604259, 985264, 117804, '<td valign="top">That is fantastic art</td>', 'That is fantastic art', '2011-11-27 02:33:56.000000', NULL, 1),
